const packingRoute=CobaltUI.route.bind(CobaltUI);CobaltUI.route=p=>CobaltPackingUI.matches(p)?CobaltPackingUI.route():packingRoute(p);const packingLanguage=CobaltUI.languageChanged.bind(CobaltUI);CobaltUI.languageChanged=()=>CobaltPackingUI.matches(location.pathname)?CobaltPackingUI.language():packingLanguage();const packingPermission=Router.permission.bind(Router);Router.permission=p=>!ProductContext.isCopper()&&AppConfig.cobaltPackingV44&&CobaltPackingUI.matches(p)?'load:read':packingPermission(p);Router.add(/^\/outbounds\/([0-9a-f-]{36})\/packing-list$/,()=>ProductContext.isCopper()?Router.go('/outbounds'):CobaltPackingUI.route());
const packingExecutionDetail=CobaltExecutionUI.detail.bind(CobaltExecutionUI);CobaltExecutionUI.detail=async function(id){await packingExecutionDetail(id);if(this.data?.execution?.state==='OUTBOUND'&&CobaltUI.can('load:read'))document.querySelector('.co-execution-page h2')?.insertAdjacentHTML('afterend','<p><a class="button primary" data-co-packing-link href="/outbounds/'+id+'/packing-list">'+CobaltPackingUI.t('Packing List 单证管理','Packing List Document Management')+'</a></p>');};const packingLoadingDetail=CobaltLoadingUI.detail.bind(CobaltLoadingUI);CobaltLoadingUI.detail=async function(id){await packingLoadingDetail(id);const d=await API.request('/cobalt/loading/plans/'+id);if(d.order?.status==='OUTBOUND'&&CobaltUI.can('load:read'))document.querySelector('.co-loading-page h2')?.insertAdjacentHTML('afterend','<p><a class="button primary" data-co-packing-link href="/outbounds/'+d.order.id+'/packing-list">'+CobaltPackingUI.t('Packing List 单证管理','Packing List Document Management')+'</a></p>');};
